import copy


def set_nested(data, path, value):
    if not path:
        raise ValueError('path')
    out = copy.deepcopy(data)
    cur = out
    for k in path[:-1]:
        if not isinstance(cur.get(k), dict):
            cur[k] = {}
        cur = cur[k]
    cur[path[-1]] = value
    return out

def get_nested(data, path, default):
