        if not isinstance(cur, dict) or k not in cur:
            return default
        cur = cur[k]
    return cur

def average_by(rows, group_key, value_key):
    sums = {}
    counts = {}
    for r in rows:
        g = r[group_key]
        sums[g] = sums.get(g, 0) + r[value_key]
        counts[g] = counts.get(g, 0) + 1
    return {g: sums[g] / counts[g] for g in sums}

